import path from "node:path";

const XML_HEADER = `<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by scripts/generate-widget-renderer-contract.mjs. Do not edit. -->`;

export function renderAndroidWidgetPickerPreviewOutputs(contract, root) {
  const resRoot = path.join(
    root,
    "modules/loofit-workout-core/android/src/main/res",
  );
  const lightPalette = contract.previewPalette.light;
  const darkPalette = contract.previewPalette.dark;
  const fixture = contract.previewFixture;
  const lightHeatColors = contract.heatmap.bucketAccentWeights.map((weight) =>
    mixHex(lightPalette.heatmapBase, lightPalette.accent, weight),
  );
  const darkHeatColors = contract.heatmap.bucketAccentWeights.map((weight) =>
    mixHex(darkPalette.heatmapBase, darkPalette.accent, weight),
  );

  const output = {
    "values/colors.xml": colorsXml(lightPalette, lightHeatColors, contract),
    "values-night/colors.xml": colorsXml(darkPalette, darkHeatColors, contract),
    "values/styles.xml": stylesXml(contract),
    "drawable/loofit_widget_background.xml": shapeXml(
      "@color/loofit_widget_preview_background",
      contract.designSystem.radius.container,
    ),
    "drawable/loofit_widget_preview_action.xml": shapeXml(
      "@color/loofit_widget_preview_accent",
      contract.control.buttonRadius,
    ),
    "drawable/loofit_widget_preview_bar.xml": shapeXml(
      "@color/loofit_widget_preview_accent",
      contract.bodyPartDuration.bar.radius,
    ),
    "layout/loofit_widget_preview_control.xml": controlPreview(
      contract,
      fixture,
    ),
    "layout/loofit_widget_preview_week.xml": weekPreview(contract, fixture),
    "layout/loofit_widget_preview_month.xml": monthPreview(contract, fixture),
    "layout/loofit_widget_preview_current_month.xml": currentMonthPreview(
      contract,
      fixture,
    ),
    "layout/loofit_widget_preview_six_months.xml": sixMonthPreview(
      contract,
      fixture,
    ),
    "layout/loofit_widget_preview_four_week.xml": fourWeekPreview(
      contract,
      fixture,
    ),
    "layout/loofit_widget_preview_routine_progress.xml": routinePreview(
      contract,
      fixture,
    ),
    "layout/loofit_widget_preview_body_part_duration.xml":
      bodyPartDurationPreview(contract, fixture),
    "layout/loofit_widget_preview_lock_workout.xml": lockWorkoutPreview(
      contract,
      fixture,
    ),
    "layout/loofit_widget_preview_lock_three_week.xml": lockHeatmapPreview(
      contract,
      fixture,
      false,
    ),
    "layout/loofit_widget_preview_lock_next_three_week.xml": lockHeatmapPreview(
      contract,
      fixture,
      true,
    ),
    "layout/loofit_widget_preview_lock_routine_progress.xml":
      lockRoutinePreview(contract, fixture),
  };

  for (let bucket = 0; bucket <= lightHeatColors.length; bucket += 1) {
    const color =
      bucket === 0
        ? "@color/loofit_widget_preview_heat_empty"
        : `@color/loofit_widget_preview_heat_${bucket}`;
    output[`drawable/loofit_widget_preview_heat_${bucket}.xml`] = shapeXml(
      color,
      contract.designSystem.radius.cell,
    );
    output[`drawable/loofit_widget_preview_today_${bucket}.xml`] =
      outlinedShapeXml(
        color,
        "@color/loofit_widget_preview_today",
        contract.heatmap.previewVariants.currentMonth.todayIndicator.width,
        contract.designSystem.radius.cell,
      );
  }
  contract.lockScreen.threeWeekCalendar.bucketOpacities.forEach(
    (opacity, index) => {
      output[`drawable/loofit_widget_preview_lock_heat_${index + 1}.xml`] =
        shapeXml(
          alphaHex("#FFFFFF", opacity),
          contract.lockScreen.threeWeekCalendar.cellRadius,
        );
    },
  );

  return new Map(
    Object.entries(output).map(([relativePath, contents]) => [
      path.join(resRoot, relativePath),
      `${contents.trim()}\n`,
    ]),
  );
}

function colorsXml(palette, heatColors, contract) {
  const colors = {
    loofit_widget_preview_background: palette.surface,
    loofit_widget_preview_surface: palette.raisedSurface,
    loofit_widget_preview_text: palette.textHigh,
    loofit_widget_preview_text_medium: palette.textMedium,
    loofit_widget_preview_text_low: palette.textLow,
    loofit_widget_preview_weekend: palette.textWeekend,
    loofit_widget_preview_accent: palette.accent,
    loofit_widget_preview_accent_text: palette.onAccent,
    loofit_widget_preview_heat_empty: palette.heatmapEmpty,
    loofit_widget_preview_today: palette.todayIndicator,
  };
  heatColors.forEach((color, index) => {
    colors[`loofit_widget_preview_heat_${index + 1}`] = color;
  });
  contract.lockScreen.threeWeekCalendar.bucketOpacities.forEach(
    (opacity, index) => {
      colors[`loofit_widget_preview_lock_text_${index + 1}`] = alphaHex(
        "#FFFFFF",
        opacity,
      );
    },
  );
  return `${XML_HEADER}
<resources>
${Object.entries(colors)
  .map(([name, color]) => `  <color name="${name}">${color}</color>`)
  .join("\n")}
</resources>`;
}

function stylesXml(contract) {
  const typography = contract.designSystem.typography;
  const control = contract.control.text;
  const routine = contract.routineProgress.textList.text;
  const lockRoutine = contract.routineProgress.textList.lockScreen.text;
  return `${XML_HEADER}
<resources>
  <style name="LoofitWidgetPreviewLabel">
    <item name="android:includeFontPadding">false</item>
    <item name="android:maxLines">1</item>
    <item name="android:textColor">@color/loofit_widget_preview_text_medium</item>
    <item name="android:textSize">${dp(contract.text.label.size, "sp")}</item>
    <item name="android:textStyle">bold</item>
  </style>
  <style name="LoofitWidgetPreviewTitle">
    <item name="android:includeFontPadding">false</item>
    <item name="android:maxLines">1</item>
    <item name="android:textColor">@color/loofit_widget_preview_text</item>
    <item name="android:textSize">${dp(control.title.size, "sp")}</item>
    <item name="android:textStyle">bold</item>
  </style>
  <style name="LoofitWidgetPreviewTimer">
    <item name="android:includeFontPadding">false</item>
    <item name="android:maxLines">1</item>
    <item name="android:textColor">@color/loofit_widget_preview_text</item>
    <item name="android:textSize">${dp(control.timer.size, "sp")}</item>
    <item name="android:textStyle">bold</item>
  </style>
  <style name="LoofitWidgetPreviewDetail">
    <item name="android:includeFontPadding">false</item>
    <item name="android:maxLines">1</item>
    <item name="android:textColor">@color/loofit_widget_preview_text_low</item>
    <item name="android:textSize">${dp(control.detail.size, "sp")}</item>
  </style>
  <style name="LoofitWidgetPreviewMeta">
    <item name="android:includeFontPadding">false</item>
    <item name="android:maxLines">1</item>
    <item name="android:textColor">@color/loofit_widget_preview_text_low</item>
    <item name="android:textSize">${dp(typography.sm.size, "sp")}</item>
  </style>
  <style name="LoofitWidgetPreviewRoutineTitle">
    <item name="android:includeFontPadding">false</item>
    <item name="android:maxLines">1</item>
    <item name="android:textSize">${dp(routine.split.size, "sp")}</item>
    <item name="android:textStyle">bold</item>
  </style>
  <style name="LoofitWidgetPreviewCell">
    <item name="android:gravity">center</item>
    <item name="android:includeFontPadding">false</item>
    <item name="android:maxLines">1</item>
    <item name="android:textColor">@color/loofit_widget_preview_text_low</item>
    <item name="android:textSize">${dp(contract.heatmap.styles.detailed.cellLabelSize, "sp")}</item>
  </style>
  <style name="LoofitWidgetPreviewLockWorkout">
    <item name="android:includeFontPadding">false</item>
    <item name="android:maxLines">1</item>
    <item name="android:textColor">@color/loofit_widget_preview_text</item>
    <item name="android:textSize">${dp(lockRoutine.workout.size, "sp")}</item>
    <item name="android:textStyle">bold</item>
  </style>
  <style name="LoofitWidgetPreviewLockRelativeDay">
    <item name="android:includeFontPadding">false</item>
    <item name="android:maxLines">1</item>
    <item name="android:textColor">@color/loofit_widget_preview_text_low</item>
    <item name="android:textSize">${dp(lockRoutine.relativeDay.size, "sp")}</item>
  </style>
</resources>`;
}

function controlPreview(contract, fixture) {
  const idle = fixture.control.idle;
  return homeRoot(
    contract,
    `
  <TextView style="@style/LoofitWidgetPreviewLabel" android:layout_width="match_parent" android:layout_height="wrap_content" android:text="${xml(idle.eyebrow)}" />
  <TextView android:layout_width="1dp" android:layout_height="0dp" android:layout_weight="1" />
  <LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="vertical">
    <TextView style="@style/LoofitWidgetPreviewTitle" android:layout_width="match_parent" android:layout_height="wrap_content" android:text="${xml(idle.title)}" />
    <TextView style="@style/LoofitWidgetPreviewDetail" android:layout_width="match_parent" android:layout_height="wrap_content" android:layout_marginTop="${dp(contract.control.bodyGap)}" android:text="${xml(idle.detail)}" />
  </LinearLayout>
  <TextView android:layout_width="1dp" android:layout_height="0dp" android:layout_weight="1" />
  <TextView android:layout_width="match_parent" android:layout_height="${dp(contract.control.buttonHeight)}" android:background="@drawable/loofit_widget_preview_action" android:gravity="center" android:includeFontPadding="false" android:text="${xml(idle.action)}" android:textColor="@color/loofit_widget_preview_accent_text" android:textSize="${dp(contract.control.text.button.size, "sp")}" android:textStyle="bold" />`,
  );
}

function weekPreview(contract, fixture) {
  const dates = rollingDates(
    fixture.previewDate ?? fixture.heatmap.anchorDate,
    7,
  );
  const stats = statsForDates(fixture, dates);
  return homeRoot(
    contract,
    `
  ${weekdayRow(contract, false)}
  ${calendarGrid(contract, fixture, [dates], { weighted: true })}
  <LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:layout_marginTop="${dp(contract.heatmap.weekFooter.topRowGap)}" android:orientation="horizontal">
    ${statColumn(contract, contract.heatmap.weekFooter.statLabels[0], `${stats.count}회`)}
    ${statColumn(contract, contract.heatmap.weekFooter.statLabels[1], formatDuration(stats.durationSeconds))}
    ${statColumn(contract, contract.heatmap.weekFooter.statLabels[2], formatDuration(Math.round(stats.durationSeconds / Math.max(stats.count, 1))))}
  </LinearLayout>
  <LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:layout_marginTop="${dp(contract.heatmap.weekFooter.recentRowGap)}" android:gravity="center_vertical" android:orientation="horizontal">
    <TextView style="@style/LoofitWidgetPreviewMeta" android:layout_width="0dp" android:layout_height="wrap_content" android:layout_weight="1" android:text="${xml(contract.heatmap.weekFooter.recentLabel)}" />
    <TextView style="@style/LoofitWidgetPreviewMeta" android:layout_width="wrap_content" android:layout_height="wrap_content" android:text="${xml(fixture.control.completed.title)} · ${xml(fixture.control.completed.duration)}" android:textColor="@color/loofit_widget_preview_text_medium" />
  </LinearLayout>`,
  );
}

function monthPreview(contract, fixture) {
  const anchor = parseDate(fixture.heatmap.anchorDate);
  const start = startOfWeek(addDays(anchor, -28));
  const rows = chunk(dateRange(start, addDays(start, 34)), 7);
  const stats = statsForDates(
    fixture,
    rows.flat().filter((date) => date <= anchor),
  );
  return homeRoot(
    contract,
    `
  ${weekdayRow(contract, false)}
  ${calendarGrid(contract, fixture, rows, { weighted: true })}
  <TextView style="@style/LoofitWidgetPreviewMeta" android:layout_width="match_parent" android:layout_height="wrap_content" android:layout_marginTop="${dp(contract.heatmap.styles.detailed.headerGap)}" android:gravity="center" android:text="${stats.count}회 · 총 ${formatDuration(stats.durationSeconds)}" android:textColor="@color/loofit_widget_preview_text_medium" />`,
  );
}

function currentMonthPreview(contract, fixture) {
  const anchor = parseDate(fixture.heatmap.anchorDate);
  const monthStart = new Date(
    Date.UTC(anchor.getUTCFullYear(), anchor.getUTCMonth(), 1),
  );
  const monthEnd = new Date(
    Date.UTC(anchor.getUTCFullYear(), anchor.getUTCMonth() + 1, 0),
  );
  const start = startOfWeek(monthStart);
  const end = endOfWeek(monthEnd);
  const rows = chunk(dateRange(start, end), 7);
  const month = anchor.getUTCMonth() + 1;
  const stats = statsForDates(fixture, dateRange(monthStart, anchor));
  return homeRoot(
    contract,
    `
  <TextView style="@style/LoofitWidgetPreviewLabel" android:layout_width="match_parent" android:layout_height="wrap_content" android:text="${month}월 · ${stats.count}회" android:textColor="@color/loofit_widget_preview_text" />
  ${weekdayRow(contract, false)}
  ${calendarGrid(contract, fixture, rows, { weighted: true, month: anchor.getUTCMonth() })}`,
  );
}

function sixMonthPreview(contract, fixture) {
  const anchor = parseDate(fixture.heatmap.anchorDate);
  const rangeStart = new Date(
    Date.UTC(anchor.getUTCFullYear(), anchor.getUTCMonth() - 5, 1),
  );
  const stats = statsForDates(fixture, dateRange(rangeStart, anchor));
  const labels = Array.from(
    { length: contract.heatmap.variants.year.rangeMonths },
    (_, index) => {
      const date = new Date(
        Date.UTC(anchor.getUTCFullYear(), anchor.getUTCMonth() - 5 + index, 1),
      );
      return `${date.getUTCMonth() + 1}월`;
    },
  );
  const columns = 30;
  const rows = Array.from({ length: 7 }, (_, row) =>
    Array.from({ length: columns }, (_, column) => ({
      compact: true,
      bucket: heatmapBucket(contract, fixture, row + column * 7),
    })),
  );
  return homeRoot(
    contract,
    `
  <LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:gravity="center_vertical" android:orientation="horizontal">
    <TextView style="@style/LoofitWidgetPreviewLabel" android:layout_width="0dp" android:layout_height="wrap_content" android:layout_weight="1" android:text="${xml(contract.heatmap.variants.year.title)}" android:textColor="@color/loofit_widget_preview_text" />
    <TextView style="@style/LoofitWidgetPreviewMeta" android:layout_width="wrap_content" android:layout_height="wrap_content" android:text="${stats.count}회 · 총 ${formatDuration(stats.durationSeconds)}" />
  </LinearLayout>
  <LinearLayout android:layout_width="match_parent" android:layout_height="${dp(contract.heatmap.sixMonth.monthLabelHeight)}" android:orientation="horizontal">
    ${labels.map((label) => `<TextView style="@style/LoofitWidgetPreviewMeta" android:layout_width="0dp" android:layout_height="match_parent" android:layout_weight="1" android:gravity="start|center_vertical" android:text="${label}" />`).join("\n    ")}
  </LinearLayout>
  ${compactGrid(rows)}`,
  );
}

function fourWeekPreview(contract, fixture) {
  const anchor = parseDate(fixture.heatmap.anchorDate);
  const start = startOfWeek(addDays(anchor, -21));
  const rows = chunk(dateRange(start, addDays(start, 27)), 7);
  return homeRoot(
    contract,
    `
  ${weekdayRow(contract, false)}
  ${expandedCalendarGrid(contract, fixture, rows)}`,
  );
}

function routinePreview(contract, fixture) {
  const spec = contract.routineProgress.textList;
  const compact = fixture.routineProgress.items.length >= spec.visibleItemLimit;
  return homeRoot(
    contract,
    fixture.routineProgress.items
      .map((item, index) => {
        const title = item.split || item.bodyParts;
        const metadata = [
          item.relativeDay,
          item.split ? item.bodyParts : "",
          item.duration,
        ]
          .filter(Boolean)
          .join(spec.metadataSeparator);
        const color =
          index === fixture.routineProgress.currentIndex
            ? "@color/loofit_widget_preview_accent"
            : "@color/loofit_widget_preview_text_low";
        return `<LinearLayout android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" android:gravity="center_vertical" android:orientation="vertical">
    <TextView style="@style/LoofitWidgetPreviewRoutineTitle" android:layout_width="match_parent" android:layout_height="wrap_content" android:text="${xml(title)}" android:textColor="${color}"${compact ? ` android:textSize="${dp(spec.compactText.split.size, "sp")}"` : ""} />
    <TextView style="@style/LoofitWidgetPreviewMeta" android:layout_width="match_parent" android:layout_height="wrap_content" android:text="${xml(metadata)}" android:textColor="${color}" />
  </LinearLayout>`;
      })
      .join("\n  "),
    compact ? spec.layoutByVisibleItemCount["4"].verticalContentPadding : undefined,
  );
}

function bodyPartDurationPreview(contract, fixture) {
  const max = Math.max(
    ...fixture.bodyPartDuration.map((item) => item.durationSeconds),
  );
  const rows = fixture.bodyPartDuration
    .slice(0, contract.bodyPartDuration.visibleItemLimit)
    .map((item) => {
      const percentage = Math.max(
        1,
        Math.round((item.durationSeconds / max) * 100),
      );
      return `<LinearLayout android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" android:gravity="center_vertical" android:orientation="vertical">
    <LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:gravity="center_vertical" android:orientation="horizontal">
      <TextView style="@style/LoofitWidgetPreviewLabel" android:layout_width="0dp" android:layout_height="wrap_content" android:layout_weight="1" android:text="${xml(item.bodyPart)}" android:textColor="@color/loofit_widget_preview_text" />
      <TextView style="@style/LoofitWidgetPreviewMeta" android:layout_width="wrap_content" android:layout_height="wrap_content" android:text="${xml(formatDuration(item.durationSeconds))}" />
    </LinearLayout>
    <LinearLayout android:layout_width="match_parent" android:layout_height="${dp(contract.bodyPartDuration.bar.height)}" android:layout_marginTop="${dp(contract.designSystem.spacing.xs)}" android:orientation="horizontal" android:weightSum="100">
      <TextView android:layout_width="0dp" android:layout_height="match_parent" android:layout_weight="${percentage}" android:background="@drawable/loofit_widget_preview_bar" />
      <TextView android:layout_width="0dp" android:layout_height="1dp" android:layout_weight="${100 - percentage}" />
    </LinearLayout>
  </LinearLayout>`;
    })
    .join("\n  ");
  return homeRoot(
    contract,
    `
  <TextView style="@style/LoofitWidgetPreviewLabel" android:layout_width="match_parent" android:layout_height="wrap_content" android:text="${xml(contract.bodyPartDuration.title)}" android:textColor="@color/loofit_widget_preview_text" />
  ${rows}`,
  );
}

function lockWorkoutPreview(contract, fixture) {
  const idle = fixture.control.idle;
  return accessoryRoot(
    contract,
    `
  <TextView android:layout_width="match_parent" android:layout_height="wrap_content" android:gravity="center" android:includeFontPadding="false" android:maxLines="1" android:text="${xml(idle.title)}" android:textColor="@color/loofit_widget_preview_text" android:textSize="${dp(contract.lockScreen.text.rectangularTitle.size, "sp")}" android:textStyle="bold" />
  <TextView android:layout_width="match_parent" android:layout_height="wrap_content" android:gravity="center" android:includeFontPadding="false" android:maxLines="1" android:text="${xml(idle.detail)}" android:textColor="@color/loofit_widget_preview_text_low" android:textSize="${dp(contract.lockScreen.text.rectangularDetail.size, "sp")}" />`,
  );
}

function lockHeatmapPreview(contract, fixture, upcoming) {
  const anchor = parseDate(fixture.heatmap.anchorDate);
  const currentWeek = startOfWeek(anchor);
  const start = upcoming ? currentWeek : addDays(currentWeek, -14);
  const rows = chunk(dateRange(start, addDays(start, 20)), 7);
  return accessoryRoot(
    contract,
    `
  ${weekdayRow(contract, true)}
  ${calendarGrid(contract, fixture, rows, { weighted: true, lock: true, futureEmpty: upcoming })}`,
  );
}

function lockRoutinePreview(contract, fixture) {
  const spec = contract.routineProgress.textList.lockScreen;
  const maxStartIndex = Math.max(
    0,
    fixture.routineProgress.items.length - spec.visibleItemLimit,
  );
  const startIndex = Math.min(
    Math.max(
      fixture.routineProgress.currentIndex - Math.floor(spec.visibleItemLimit / 2),
      0,
    ),
    maxStartIndex,
  );
  const columns = fixture.routineProgress.items
    .slice(startIndex, startIndex + spec.visibleItemLimit)
    .map((item, index) => {
      const color =
        startIndex + index === fixture.routineProgress.currentIndex
          ? "@color/loofit_widget_preview_text"
          : "@color/loofit_widget_preview_text_low";
      return `<LinearLayout android:layout_width="0dp" android:layout_height="match_parent" android:layout_weight="1" android:gravity="center" android:orientation="vertical">
    <TextView style="@style/LoofitWidgetPreviewLockWorkout" android:layout_width="match_parent" android:layout_height="wrap_content" android:gravity="center" android:text="${xml(item.split || item.bodyParts)}" android:textColor="${color}" />
    <TextView style="@style/LoofitWidgetPreviewLockRelativeDay" android:layout_width="match_parent" android:layout_height="wrap_content" android:layout_marginTop="${dp(spec.itemGap)}" android:gravity="center" android:text="${xml(item.relativeDay)}" android:textColor="${color}" />
  </LinearLayout>`;
    })
    .join("\n  ");
  return `${XML_HEADER}
<LinearLayout xmlns:android="http://schemas.android.com/apk/res/android" android:layout_width="match_parent" android:layout_height="match_parent" android:background="@drawable/loofit_widget_background" android:orientation="horizontal" android:padding="${dp(spec.contentPadding)}">
  ${columns}
</LinearLayout>`;
}

function homeRoot(contract, children, verticalPadding) {
  const paddingAttributes = verticalPadding === undefined
    ? `android:padding="${dp(contract.card.contentPadding)}"`
    : `android:paddingHorizontal="${dp(contract.card.contentPadding)}" android:paddingVertical="${dp(verticalPadding)}"`;
  return `${XML_HEADER}
<LinearLayout xmlns:android="http://schemas.android.com/apk/res/android" android:layout_width="match_parent" android:layout_height="match_parent" android:background="@drawable/loofit_widget_background" android:orientation="vertical" ${paddingAttributes}>
${children.trimEnd()}
</LinearLayout>`;
}

function accessoryRoot(contract, children) {
  return `${XML_HEADER}
<LinearLayout xmlns:android="http://schemas.android.com/apk/res/android" android:layout_width="match_parent" android:layout_height="match_parent" android:background="@drawable/loofit_widget_background" android:gravity="center" android:orientation="vertical" android:padding="${dp(contract.lockScreen.threeWeekCalendar.contentPadding)}">
${children.trimEnd()}
</LinearLayout>`;
}

function weekdayRow(contract, lock) {
  const size = lock
    ? contract.lockScreen.threeWeekCalendar.weekdayLabelSize
    : contract.heatmap.styles.detailed.cellLabelSize;
  return `<LinearLayout android:layout_width="match_parent" android:layout_height="${dp(size + 4)}" android:orientation="horizontal">
    ${contract.heatmap.weekdayLabels
      .map((label) => {
        const color = lock
          ? contract.lockScreen.threeWeekCalendar.dimmedWeekdayLabels.includes(
              label,
            )
            ? "@color/loofit_widget_preview_text_low"
            : "@color/loofit_widget_preview_text_medium"
          : contract.heatmap.weekdayLabelColorPolicy.weekendLabels.includes(
                label,
              )
            ? "@color/loofit_widget_preview_weekend"
            : "@color/loofit_widget_preview_text_low";
        return `<TextView android:layout_width="0dp" android:layout_height="match_parent" android:layout_weight="1" android:gravity="center" android:includeFontPadding="false" android:text="${label}" android:textColor="${color}" android:textSize="${dp(size, "sp")}" />`;
      })
      .join("\n    ")}
  </LinearLayout>`;
}

function calendarGrid(contract, fixture, rows, options = {}) {
  const anchor = parseDate(fixture.heatmap.anchorDate);
  return `<LinearLayout android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" android:orientation="vertical">
    ${rows
      .map(
        (
          row,
        ) => `<LinearLayout android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" android:orientation="horizontal">
      ${row
        .map((date, index) => {
          const outside =
            options.month !== undefined && date.getUTCMonth() !== options.month;
          const future = date > anchor;
          const suppressFuture = options.futureEmpty && future;
          const dayIndex = daysBetween(date, anchor);
          const bucket = future
            ? 0
            : heatmapBucket(contract, fixture, dayIndex);
          const isToday = sameDay(date, anchor);
          let background = "@android:color/transparent";
          if (!outside && !suppressFuture) {
            if (options.lock) {
              background =
                bucket === 0
                  ? "@android:color/transparent"
                  : `@drawable/loofit_widget_preview_lock_heat_${bucket}`;
            } else {
              background = `@drawable/loofit_widget_preview_${isToday ? "today" : "heat"}_${bucket}`;
            }
          }
          const color = options.lock
            ? "@color/loofit_widget_preview_text"
            : bucket >=
                contract.heatmap.cellLabelColorPolicy.strongMinimumBucket
              ? "@color/loofit_widget_preview_accent_text"
              : bucket > 0
                ? "@color/loofit_widget_preview_text"
                : "@color/loofit_widget_preview_text_low";
          return `<TextView style="@style/LoofitWidgetPreviewCell" android:layout_width="0dp" android:layout_height="match_parent" android:layout_weight="1" android:layout_margin="${dp((options.lock ? contract.lockScreen.threeWeekCalendar.cellGap : contract.heatmap.styles.detailed.cellGap) / 2)}" android:background="${background}" android:text="${date.getUTCDate()}" android:textColor="${color}" />`;
        })
        .join("\n      ")}
    </LinearLayout>`,
      )
      .join("\n    ")}
  </LinearLayout>`;
}

function expandedCalendarGrid(contract, fixture, rows) {
  const groups = ["가슴", "등·이두", "하체", "어깨"];
  return `<LinearLayout android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" android:orientation="vertical">
    ${rows
      .map(
        (
          row,
        ) => `<LinearLayout android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" android:orientation="horizontal">
      ${row
        .map((date, index) => {
          const bucket = heatmapBucket(
            contract,
            fixture,
            daysBetween(date, parseDate(fixture.heatmap.anchorDate)),
          );
          const background = `@drawable/loofit_widget_preview_heat_${bucket}`;
          return `<LinearLayout android:layout_width="0dp" android:layout_height="match_parent" android:layout_weight="1" android:layout_margin="${dp(contract.heatmap.styles.expanded.cellGap / 2)}" android:background="${background}" android:gravity="center" android:orientation="vertical" android:padding="${dp(contract.heatmap.styles.expanded.cellContentGap)}">
        <TextView style="@style/LoofitWidgetPreviewCell" android:layout_width="match_parent" android:layout_height="wrap_content" android:text="${date.getUTCDate()}" android:textColor="${bucket >= 3 ? "@color/loofit_widget_preview_accent_text" : "@color/loofit_widget_preview_text"}" />
        <TextView style="@style/LoofitWidgetPreviewMeta" android:layout_width="match_parent" android:layout_height="wrap_content" android:gravity="center" android:maxLines="1" android:text="${bucket > 0 ? groups[index % groups.length] : ""}" android:textColor="${bucket >= 3 ? "@color/loofit_widget_preview_accent_text" : "@color/loofit_widget_preview_text_medium"}" />
      </LinearLayout>`;
        })
        .join("\n      ")}
    </LinearLayout>`,
      )
      .join("\n    ")}
  </LinearLayout>`;
}

function compactGrid(rows) {
  return `<LinearLayout android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" android:orientation="vertical">
    ${rows
      .map(
        (
          row,
        ) => `<LinearLayout android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" android:orientation="horizontal">
      ${row.map((cell) => `<TextView android:layout_width="0dp" android:layout_height="match_parent" android:layout_weight="1" android:layout_margin="1dp" android:background="@drawable/loofit_widget_preview_heat_${cell.bucket}" />`).join("\n      ")}
    </LinearLayout>`,
      )
      .join("\n    ")}
  </LinearLayout>`;
}

function statColumn(contract, label, value) {
  return `<LinearLayout android:layout_width="0dp" android:layout_height="wrap_content" android:layout_weight="1" android:orientation="vertical">
      <TextView style="@style/LoofitWidgetPreviewMeta" android:layout_width="match_parent" android:layout_height="wrap_content" android:text="${xml(label)}" />
      <TextView android:layout_width="match_parent" android:layout_height="wrap_content" android:includeFontPadding="false" android:maxLines="1" android:text="${xml(value)}" android:textColor="@color/loofit_widget_preview_text" android:textSize="${dp(contract.heatmap.weekFooter.statValueSize, "sp")}" android:textStyle="bold" />
    </LinearLayout>`;
}

function heatmapBucket(contract, fixture, offset) {
  const pattern = fixture.heatmap.durationPatternSeconds;
  const seconds =
    pattern[
      ((Math.abs(offset) % pattern.length) + pattern.length) % pattern.length
    ];
  if (seconds <= 0) return 0;
  const thresholdIndex = contract.heatmap.bucketThresholdSeconds.findIndex(
    (threshold) => seconds < threshold,
  );
  return thresholdIndex === -1
    ? contract.heatmap.bucketAccentWeights.length
    : thresholdIndex + 1;
}

function statsForDates(fixture, dates) {
  const anchor = parseDate(fixture.heatmap.anchorDate);
  return dates.reduce(
    (stats, date) => {
      const seconds = previewDuration(fixture, daysBetween(date, anchor));
      return {
        count: stats.count + (seconds > 0 ? 1 : 0),
        durationSeconds: stats.durationSeconds + seconds,
      };
    },
    { count: 0, durationSeconds: 0 },
  );
}

function previewDuration(fixture, offset) {
  const pattern = fixture.heatmap.durationPatternSeconds;
  return (
    pattern[
      ((Math.abs(offset) % pattern.length) + pattern.length) % pattern.length
    ] ?? 0
  );
}

function shapeXml(color, radius) {
  return `${XML_HEADER}
<shape xmlns:android="http://schemas.android.com/apk/res/android" android:shape="rectangle">
  <solid android:color="${color}" />
  <corners android:radius="${dp(radius)}" />
</shape>`;
}

function outlinedShapeXml(fill, stroke, strokeWidth, radius) {
  return `${XML_HEADER}
<shape xmlns:android="http://schemas.android.com/apk/res/android" android:shape="rectangle">
  <solid android:color="${fill}" />
  <stroke android:width="${dp(strokeWidth)}" android:color="${stroke}" />
  <corners android:radius="${dp(radius)}" />
</shape>`;
}

function mixHex(from, to, weight) {
  const a = rgb(from);
  const b = rgb(to);
  return `#${[0, 1, 2]
    .map((index) =>
      Math.round(a[index] + (b[index] - a[index]) * weight)
        .toString(16)
        .padStart(2, "0"),
    )
    .join("")}`.toUpperCase();
}

function alphaHex(color, opacity) {
  const alpha = Math.round(opacity * 255)
    .toString(16)
    .padStart(2, "0");
  return `#${alpha}${color.replace("#", "")}`.toUpperCase();
}

function rgb(color) {
  const hex = color.replace("#", "");
  return [0, 2, 4].map((offset) =>
    Number.parseInt(hex.slice(offset, offset + 2), 16),
  );
}

function rollingDates(anchorValue, count) {
  const anchor = parseDate(anchorValue);
  return dateRange(addDays(anchor, -(count - 1)), anchor);
}

function dateRange(start, end) {
  const result = [];
  for (let date = start; date <= end; date = addDays(date, 1))
    result.push(date);
  return result;
}

function startOfWeek(date) {
  return addDays(date, -date.getUTCDay());
}

function endOfWeek(date) {
  return addDays(date, 6 - date.getUTCDay());
}

function addDays(date, amount) {
  const result = new Date(date);
  result.setUTCDate(result.getUTCDate() + amount);
  return result;
}

function daysBetween(date, anchor) {
  return Math.round((anchor.getTime() - date.getTime()) / 86_400_000);
}

function sameDay(left, right) {
  return left.toISOString().slice(0, 10) === right.toISOString().slice(0, 10);
}

function parseDate(value) {
  return new Date(`${value}T00:00:00.000Z`);
}

function chunk(items, size) {
  const result = [];
  for (let index = 0; index < items.length; index += size) {
    result.push(items.slice(index, index + size));
  }
  return result;
}

function formatDuration(seconds) {
  const minutes = Math.round(seconds / 60);
  const hours = Math.floor(minutes / 60);
  const remainder = minutes % 60;
  if (hours === 0) return `${minutes}분`;
  return remainder === 0 ? `${hours}시간` : `${hours}시간 ${remainder}분`;
}

function dp(value, unit = "dp") {
  return `${Number(value).toFixed(Number.isInteger(Number(value)) ? 0 : 1)}${unit}`;
}

function xml(value) {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}
